// Map form labels -> GHL option KEYS (GHL strips hyphens/spaces from keys).
// Two entry points share this pipeline: the n8n form (fields at the top
// level) and the console (JSON under .body). Same field LABELS either way.
const _in = $input.first().json;
const viaConsole = !!(_in && _in.body && typeof _in.body === 'object' && !Array.isArray(_in.body));
const f = viaConsole ? _in.body : _in;
const key = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const TYPE_KEY = { 'SFR':'sfr', '2-4 Unit':'2to4unit', '5+ Unit':'5plusunit', 'Condo':'condo', 'Land':'land' };
const OCC_KEY = { 'VACANT AT CLOSE':'vacantatclose', 'Vacant Now':'vacantnow', 'Tenant Occupied':'tenantoccupied', 'Owner Occupied':'owneroccupied', 'Occupancy Unknown':'unknown' };
const num = (v) => (v === '' || v == null) ? undefined : Number(v);
const txt = (v) => (v == null ? '' : String(v).trim());

const address = txt(f['Address']);

// City and Zip are no longer separate inputs - derive them from the address so
// prop_city / prop_zip stay populated. Both are DISPLAY-ONLY (the teaser prompt
// and the GHL record); the match engine keys on County, which is still its own
// dropdown. A parse miss is cosmetic, never a mis-match.
const zipMatch = address.match(/\b(\d{5})(?:-\d{4})?\s*$/);
const derivedZip = zipMatch ? zipMatch[1] : '';
let derivedCity = '';
{
  // strip the trailing ", FL 33142" / " FL 33142"
  let head = address.replace(/[,\s]*\bFL\b[,\s]*\d{5}(?:-\d{4})?\s*$/i, '').trim();
  head = head.replace(/[,\s]+$/, '');
  if (head.indexOf(',') !== -1) {
    derivedCity = head.slice(head.lastIndexOf(',') + 1).trim();      // "123 St, Miami"
  } else if (head.indexOf('.') !== -1) {
    derivedCity = head.slice(head.lastIndexOf('.') + 1).trim();      // "2165 NW 58th St. Miami"
  }
  if (!derivedCity) {
    const w = head.split(/\s+/);
    derivedCity = w.length ? w[w.length - 1] : '';
  }
}

// Standard escrow unless the dispo manager overrides it.
const escrow = (!f['Escrow'] || Number(f['Escrow']) <= 0) ? 10000 : Number(f['Escrow']);

const _viaConsole = viaConsole;
const props = {
  prop_address: address,
  prop_city: derivedCity,
  prop_zip: derivedZip,
  prop_county: key(f['County']),
  prop_type: TYPE_KEY[f['Property Type']],
  prop_headline: txt(f['Headline']),
  prop_occupancy: OCC_KEY[f['Occupancy']],
  prop_comps: txt(f['Comps']),
  prop_description: txt(f['Additional Details']),
  prop_dispo_status: 'intake',
};
const put = (k, v) => { if (v !== undefined && v !== '') props[k] = v; };
// prop_neighborhood is a fixed GHL picklist - an unrecognised value 400s the
// whole request, so validate and drop rather than fail the run.
const HOOD_KEYS = ["allapattah", "aventura", "balharbour", "bayharborislands", "belleglade", "bocaraton", "boyntonbeach", "brickell", "coconutcreek", "coconutgrove", "coopercity", "coralgables", "coralsprings", "coralway", "cutlerbay", "daniabeach", "davie", "deerfieldbeach", "delraybeach", "doral", "downtownmiami", "edgewater", "elportal", "floridacity", "fortlauderdale", "goldenglades", "greenacres", "hallandalebeach", "hialeah", "hialeahgardens", "hollywood", "homestead", "jupiter", "kendall", "keybiscayne", "lakeworthbeach", "lantana", "lauderdalelakes", "lauderhill", "libertycity", "lighthousepoint", "littlehaiti", "littlehavana", "loxahatchee", "margate", "miamibeach", "miamigardens", "miamilakes", "miamishores", "miamisprings", "miramar", "modelcity", "northbayvillage", "northlauderdale", "northmiami", "northmiamibeach", "oaklandpark", "opalocka", "other", "overtown", "palmbeachgardens", "palmettobay", "parkland", "pembrokepines", "perrine", "pinecrest", "plantation", "pompanobeach", "richmondheights", "rivierabeach", "royalpalmbeach", "southmiami", "sunnyislesbeach", "sunrise", "surfside", "sweetwater", "tamarac", "theroads", "uppereastside", "virginiagardens", "wellington", "westchester", "westmiami", "weston", "westpalmbeach", "wiltonmanors", "wynwood"];
const hoodKey = f['Neighborhood'] ? key(f['Neighborhood']) : '';
put('prop_neighborhood', HOOD_KEYS.indexOf(hoodKey) !== -1 ? hoodKey : undefined);
put('prop_beds', num(f['Beds']));
put('prop_baths', num(f['Baths']));
put('prop_sqft', num(f['Living Area Sqft']));
put('prop_lot_sqft', num(f['Lot Size Sqft']));
put('prop_year_built', num(f['Year Built']));
put('prop_roof_age', txt(f['Roof Age']));
put('prop_ac_age', txt(f['AC Age']));
put('prop_key_upgrades', txt(f['Key Upgrades']));
put('prop_hoa', txt(f['HOA']));
put('prop_liens_violations', txt(f['Liens or Violations']));
put('prop_highlights', txt(f['Extra Highlights']));
put('prop_asking_price', num(f['Asking Price']));
put('prop_arv', num(f['ARV']));
put('prop_repair_est', num(f['Repair Estimate']));
put('prop_emd_terms', '$' + escrow.toLocaleString('en-US'));
put('prop_photos_url', txt(f['Photos Videos URL']));
put('prop_close_date', txt(f['Close Date']));
put('prop_access_notes', txt(f['Access Notes']));

// MAO deliberately NOT computed — settled during acquisition.

return [{ json: { viaConsole: _viaConsole, props, address, searchQuery: address, escrow, derivedCity, derivedZip, raw: f } }];

// prop_address is UNIQUE in GHL. A blind create fails once the acquisition
// side has already filed the house, so decide create vs update here.
const search = $input.first().json;
const intake = $('Normalize + Map Keys').first().json;
const norm = (s) => (s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const target = norm(intake.address);
const hit = (search.records || []).find(r => norm(r.properties?.prop_address) === target);
return [{ json: { ...intake, exists: !!hit, recordId: hit ? hit.id : null } }];

// ============================================================
// EXCLUSION ENGINE — default is INCLUDE.
//
// Extracted buy_* data is a GUESS (parsed from old prose notes, never
// confirmed with the buyer). It is NEVER used to filter a blast. Using it to
// filter means a buyer whose 2024 note said "Broward only" silently stops
// hearing about Dade deals and nobody ever finds out.
//
// A buyer drops out of a blast ONLY when a human set an excl_* rule after
// actually talking to them.
//
// The buy_* data still earns its keep: where it CONTRADICTS the deal but no
// excl_* rule exists, it produces a review suggestion — an interview queue.
// ============================================================
const pages = $input.all();
const pool = pages.flatMap(p => p.json.contacts || []);

const deal = $('Create or Update?').first().json;
const p = deal.props, f = deal.raw;

// GHL returns a contact's customFields as [{id, value}] with NO field name,
// so look the id up from the definitions first. Without this every lookup
// returns null and no excl_ rule can ever fire - a silent, invisible failure.
const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID_BY_NAME = {};
for (const d of defs) ID_BY_NAME[d.name] = d.id;

const cf = (c, name) => {
  const id = ID_BY_NAME[name];
  const hit = (c.customFields || []).find(x => x.id === id || x.id === name || x.key === name);
  if (!hit) return null;
  return hit.value !== undefined ? hit.value : (hit.fieldValue !== undefined ? hit.fieldValue : null);
};
const arr = (v) => v == null ? [] : (Array.isArray(v) ? v : String(v).split(';').map(s => s.trim()).filter(Boolean));
const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// GHL stores a picklist KEY on the record ('2to4unit') but the buyer's field
// holds the LABEL ('2-4 Unit'), and norm() maps those to '2to4unit' and
// '24unit' - which never match. A buyer who told us 'no 2-4 units' was being
// blasted 2-4 units. Invisible until now because every deal has been an SFR.
const TYPE_ALIAS = { '2to4unit': '24unit', '5plusunit': '5unit',
                     'manufacturedhome': 'manufactured', 'mfg': 'manufactured' };
const canonType = (s) => { const t = norm(s); return TYPE_ALIAS[t] || t; };
const n = (v) => (v == null || v === '') ? null : Number(v);


// Address comparison for deal-scoping.
//
// 2026-08-25: comparing the WHOLE address was wrong. InvestorBase stamped
// "1125 Highview Rd, Lantana, FL 33462" while the deal was entered as
// "1125 Highview Rd Lake Worth FL 33462". Both are correct - ZIP 33462
// straddles a municipal line, so USPS says Lake Worth and the municipality is
// Lantana - but neither string contains the other, so all 76 buyers
// InvestorBase pulled for this address were counted as General cold.
//
// Compare what actually identifies a property instead: the STREET (house
// number + name, suffix canonicalised so "Rd" == "Road", ordinals reduced so
// "58 St" == "58th St") and the ZIP when both sides carry one. City and state
// are ignored on purpose - they are the parts the two systems disagree about.
//
// When either side has no parseable street - InvestorBase pulls like
// "4200 Dispo" carry no suffix - it falls back to the old containment test
// rather than silently dropping the buyer.
const ST_SUFFIX = {
  st: 'st', street: 'st', rd: 'rd', road: 'rd', ave: 'ave', av: 'ave',
  avenue: 'ave', dr: 'dr', drive: 'dr', ln: 'ln', lane: 'ln', ct: 'ct',
  court: 'ct', blvd: 'blvd', boulevard: 'blvd', ter: 'ter', terr: 'ter',
  terrace: 'ter', pl: 'pl', place: 'pl', way: 'way', cir: 'cir',
  circle: 'cir', pkwy: 'pkwy', parkway: 'pkwy', hwy: 'hwy', highway: 'hwy',
  trl: 'trl', trail: 'trl', loop: 'loop', run: 'run', path: 'path',
  sq: 'sq', square: 'sq', cv: 'cv', cove: 'cv', pt: 'pt', point: 'pt',
  xing: 'xing', crossing: 'xing', bnd: 'bnd', bend: 'bnd',
};
const DIRECTION = {
  north: 'n', south: 's', east: 'e', west: 'w', northeast: 'ne',
  northwest: 'nw', southeast: 'se', southwest: 'sw',
};
// Canonical token string: lowercase words, single spaces, street ordinals cut
// to digits, directionals abbreviated. Keeping the SPACES is what makes the
// street and the ZIP recoverable below - the old version flattened them away.
const normAddr = (s) => String(s == null ? '' : s).toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean)
  .map((t) => {
    const ord = t.match(/^(\d+)(?:st|nd|rd|th)$/);
    return ord ? ord[1] : (DIRECTION[t] || t);
  }).join(' ');
const addrParts = (norm) => {
  const toks = String(norm || '').split(' ').filter(Boolean);
  // The ZIP is the LAST five-digit token and never the first: a house number
  // like "10250" is five digits too.
  let zip = '';
  for (let i = 1; i < toks.length; i++) if (/^\d{5}$/.test(toks[i])) zip = toks[i];
  let street = '';
  if (toks.length && /^\d/.test(toks[0])) {
    const out = [toks[0]];
    for (let i = 1; i < toks.length; i++) {
      const suf = ST_SUFFIX[toks[i]];
      if (suf) { out.push(suf); street = out.join(''); break; }
      out.push(toks[i]);
    }
  }
  return { street: street, zip: zip, flat: toks.join('') };
};
const addrMatch = (a, b) => {
  if (!a || !b) return false;
  const pa = addrParts(a);
  const pb = addrParts(b);
  if (pa.street && pb.street) {
    if (pa.street !== pb.street) return false;
    // The same street name exists in many ZIPs. Demand a ZIP match only when
    // both sides actually carry one, so a bare "1125 Highview Rd" still counts.
    if (pa.zip && pb.zip) return pa.zip === pb.zip;
    return true;
  }
  return pa.flat === pb.flat
    || pa.flat.indexOf(pb.flat) !== -1
    || pb.flat.indexOf(pa.flat) !== -1;
};
const dealAddr = normAddr(p.prop_address);
const dealCounty = norm(f['County']);
const dealHood   = norm(f['Neighborhood'] || '');
const dealType   = canonType(f['Property Type']);
const asking = n(p.prop_asking_price);
const sqft   = n(p.prop_sqft);

let included = [], excluded = [], suppressed = [], suggestions = [];
let notBuyers = 0;

for (const c of pool) {
  const name = [c.firstName, c.lastName].filter(Boolean).join(' ') || c.contactName || '(no name)';
  const tier = cf(c, 'buy_tier') || '(none)';
  const srcList = arr(cf(c, 'buy_source'));
  const src = srcList.length ? srcList.join(', ') : '(none)';
  // Recency answers the real question: did the InvestorBase import for
  // THIS deal actually finish before the form was submitted?
  const addedMs = c.dateAdded ? Date.parse(c.dateAdded) : 0;
  const freshlyAdded = addedMs > 0 && (Date.now() - addedMs) < 2 * 60 * 60 * 1000;
  // buy_type rides along so the console can offer a per-blast hold by type
  // (JV partners and realtors are deliberately held from the first blast).
  // It is NEVER an exclusion here - holding is the dispo manager's call at
  // send time, not a property of the buyer.
  const types = arr(cf(c, 'buy_type'));
  const row = { id: c.id, name, phone: c.phone || null, tier, source: src, types, freshlyAdded, segment: '' };

  // ---- HARD SUPPRESSIONS: not preferences. Compliance and physics. ----
  // record_type must positively say Buyer. A blank record_type is NOT an
  // implicit buyer - seller leads, inbound web contacts and CRM demo records
  // all arrive with it empty, and none of them should get a wholesale blast.
  // This is a classification check, not a preference, so it is not subject to
  // the exclusion-by-default rule.
  const rt = arr(cf(c, 'record_type')).map(norm);
  if (!rt.includes('buyer')) { notBuyers++; continue; }

  const status = norm(cf(c, 'buy_status'));
  if (status === 'dnc' || status === 'blacklist') {
    suppressed.push({ ...row, why: 'buy_status=' + status });
    continue;
  }
  // GHL sets dnd on a contact itself when they reply STOP - that happens at the
  // carrier level, before any of our code sees the message. W2 already refuses
  // to text a dnd contact; checking it HERE too is what stops the review page
  // counting somebody the send will silently drop.
  if (c.dnd === true) { suppressed.push({ ...row, why: 'contact DND is on' }); continue; }
  if (!c.phone) { suppressed.push({ ...row, why: 'no phone on file' }); continue; }
  // ---- VETTING GATE ----
  // InvestorLift inquiries arrive as buy_vetted=Unvetted because some of them
  // are competing wholesalers fishing for the address, not buyers. A dispo
  // agent flips one field - buy_vetted=Vetted - and they blast normally
  // forever after. Rejected means confirmed snake: held permanently, kept on
  // file so we never have to re-learn who they are.
  // BLANK IS BLASTABLE. The 121 master buyers and every InvestorBase import
  // have no value here and must not be affected.
  const vetted = norm(cf(c, 'buy_vetted'));
  if (vetted === 'unvetted') { suppressed.push({ ...row, why: 'not vetted yet - dispo must set buy_vetted=Vetted' }); continue; }
  if (vetted === 'rejected') { suppressed.push({ ...row, why: 'buy_vetted=Rejected (known snake)' }); continue; }

  // ---- EXCLUSION RULES: the only thing that removes a buyer ----
  const why = [];

  if (norm(cf(c, 'excl_all_blasts')) === 'yes') why.push('held from all blasts');

  // ---- InvestorBase buyers are DEAL-SCOPED ----
  // IB returns buyers within ~2 miles of one subject property. They were never
  // a general buyer list, so they are only eligible for the deal they were
  // pulled for. Master-list buyers (BH Main / Referral) get everything.
  const srcNorm = arr(cf(c, 'buy_source')).map(norm);
  // SEGMENT, do not exclude. Source decides the SCRIPT, not eligibility.
  // An InvestorBase buyer sourced for another property is still a real cash
  // buyer in this county - excluding them would throw away the database the
  // imports exist to build.

  // ---- DNC + LITIGATOR SCRUB ----
  // Two separate things, and both are hard stops.
  //
  // A scrub HIT is never sendable, whatever the source. A TCPA litigator on a
  // purchased list is someone whose business is collecting statutory damages,
  // and Florida's FTSA carries a private right of action at $500 a text.
  const scrub = norm(cf(c, 'buy_scrub_result'));
  if (scrub === 'dnc' || scrub === 'litigator') {
    suppressed.push({ ...row, why: 'scrub hit: ' + scrub });
    continue;
  }

  // A buyer we PURCHASED and have no relationship with must be scrubbed before
  // they are ever texted. Someone on the master list opted in to hearing from
  // us; a skip-traced stranger from InvestorBase did not, and is exactly who
  // the federal and Florida registries exist to protect.
  // Being UNSCRUBBED is not a suppression - it is a hold the dispo manager can
  // release on the review page, the same way JV and Realtor work. Suppressing
  // it here would hide these buyers from the count entirely and there would be
  // nothing to release. A confirmed DNC or litigator hit above is different:
  // that one is never releasable.
  const onMasterList = srcNorm.includes('bhmain') || srcNorm.includes('referral');
  row.scrubOk = onMasterList || scrub === 'clean';
  const pulledLines = String(cf(c, 'buy_ib_property') || '')
    .split(/[;\n]/).map(s => normAddr(s)).filter(Boolean);
  const geoMatched = pulledLines.some(a => addrMatch(a, dealAddr));
  // The 'Inquired' segment is gone: it only ever meant an InvestorLift buyer
  // who raised a hand on THIS property, and InvestorLift is not wired up.
  // Jorge, 2026-08-20: 'remove inquired across the board... im not going to
  // wire up investorlift for now.' If it comes back, this is where it starts.
  let segment;
  if (srcNorm.includes('bhmain') || srcNorm.includes('referral')) segment = 'warm';
  else if (geoMatched) segment = 'geo_cold';
  else segment = 'general_cold';


  const belowPrice = n(cf(c, 'excl_below_price'));
  if (belowPrice && asking && asking < belowPrice)
    why.push('asking ' + asking + ' below their floor ' + belowPrice);

  const abovePrice = n(cf(c, 'excl_above_price'));
  if (abovePrice && asking && asking > abovePrice)
    why.push('asking ' + asking + ' above their ceiling ' + abovePrice);

  const belowSqft = n(cf(c, 'excl_below_sqft'));
  if (belowSqft && sqft && sqft < belowSqft)
    why.push('sqft ' + sqft + ' below their floor ' + belowSqft);

  const exTypes = arr(cf(c, 'excl_prop_types')).map(canonType);
  if (exTypes.length && dealType && exTypes.includes(dealType))
    why.push('excludes ' + f['Property Type']);

  const onlyCounties = arr(cf(c, 'excl_outside_counties')).map(norm);
  if (onlyCounties.length && dealCounty && !onlyCounties.includes(dealCounty))
    why.push('outside their counties');

  const onlyHoods = arr(cf(c, 'excl_outside_neighborhoods')).map(norm);
  if (onlyHoods.length && dealHood && !onlyHoods.includes(dealHood))
    why.push('outside their sub-markets');

  if (why.length) {
    excluded.push({ ...row, why: why.join('; '),
                    note: cf(c, 'excl_notes') || '', verified: cf(c, 'excl_verified_date') || '' });
    continue;
  }

  // ---- INCLUDED. Now: does unverified buy_* data hint at a missing rule? ----
  const hints = [];
  const bCounties = arr(cf(c, 'buy_counties')).map(norm);
  if (!onlyCounties.length && bCounties.length && dealCounty && !bCounties.includes(dealCounty))
    hints.push('notes say ' + arr(cf(c, 'buy_counties')).join('/') + ' only');

  const bHoods = arr(cf(c, 'buy_neighborhoods'));
  if (!onlyHoods.length && bHoods.length && dealHood && !bHoods.map(norm).includes(dealHood))
    hints.push('notes say ' + bHoods.join('/') + ' only');

  const bMin = n(cf(c, 'buy_price_min'));
  if (!belowPrice && bMin && asking && asking < bMin) hints.push('notes say min ' + bMin);

  const bMax = n(cf(c, 'buy_price_max'));
  if (!abovePrice && bMax && asking && asking > bMax) hints.push('notes say max ' + bMax);

  const bSqft = n(cf(c, 'buy_sqft_min'));
  if (!belowSqft && bSqft && sqft && sqft < bSqft) hints.push('notes say min ' + bSqft + ' sqft');

  const bTypes = arr(cf(c, 'buy_prop_types'));
  if (!exTypes.length && bTypes.length && dealType && !bTypes.map(canonType).includes(dealType))
    hints.push('notes say ' + bTypes.join('/') + ' only');

  row.segment = segment;
  included.push(row);
  if (hints.length) suggestions.push({ ...row, hint: hints.join('; '),
                                       action: 'CONFIRM WITH BUYER, then set an excl_ rule if true' });
}


// ---- Deduplicate on phone. One human, one text. ----
// Records are joined on phone at IMPORT time, so duplicates here mean two
// contact records carrying the SAME number - a merge that never happened, a
// manual entry, a re-import under a second record. Whatever the cause, the
// buyer must not receive the same deal twice, and definitely not once warm and
// once cold.
const TIER_RANK = { VIP: 0, A: 1, B: 2, C: 3 };
const SEG_RANK = { warm: 0, geo_cold: 1, general_cold: 2 };
const phoneKey = (p) => String(p == null ? '' : p).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
// Keep the record most likely to be the curated one: best tier, then warmest
// segment, then whichever was already ahead in the list.
const betterOf = (a, b) => {
  const ta = TIER_RANK[a.tier] == null ? 9 : TIER_RANK[a.tier];
  const tb = TIER_RANK[b.tier] == null ? 9 : TIER_RANK[b.tier];
  if (ta !== tb) return ta < tb ? a : b;
  const sa = SEG_RANK[a.segment] == null ? 9 : SEG_RANK[a.segment];
  const sb = SEG_RANK[b.segment] == null ? 9 : SEG_RANK[b.segment];
  if (sa !== sb) return sa < sb ? a : b;
  return a;
};

const byPhone = new Map();
const dropped = [];
for (const b of included) {
  const k = phoneKey(b.phone);
  if (!k) continue;
  const prev = byPhone.get(k);
  if (!prev) { byPhone.set(k, b); continue; }
  const keep = betterOf(prev, b);
  byPhone.set(k, keep);
  dropped.push(keep === prev ? b : prev);
}
const kept = new Set(Array.from(byPhone.values()));
const deduped = included.filter(b => kept.has(b));
const dupePhonesRemoved = included.length - deduped.length;
included = deduped;
for (const d of dropped) {
  const winner = byPhone.get(phoneKey(d.phone));
  suppressed.push(Object.assign({}, d, {
    why: 'duplicate phone - same number as ' + (winner ? winner.name : 'another buyer') + ', who is on the list'
  }));
}

const rank = { VIP: 0, A: 1, B: 2, C: 3 };
included.sort((a, b) => (rank[a.tier] ?? 9) - (rank[b.tier] ?? 9));

return [{ json: {
  recordId: deal.recordId,
  viaConsole: !!deal.viaConsole,
  created: !deal.exists,
  props: p,
  raw: f,
  pagesFetched: pages.length,
  poolSize: pool.length,
  notBuyers,
  fieldDefsLoaded: Object.keys(ID_BY_NAME).length,
  includedCount: included.length,
  dupePhonesRemoved,
  bySegment: (function () {
    const m = { warm: 0, geo_cold: 0, general_cold: 0 };
    for (const b of included) if (b.segment) m[b.segment] = (m[b.segment] || 0) + 1;
    return m;
  })(),
  // Exact counts for the per-type hold. Grouping by the buyer's FULL type set
  // (not a per-type tally) is what makes the arithmetic exact when someone
  // carries two types - Rob Noel is JV;Realtor and must not be subtracted
  // twice, and Angie Gomez is Flipper;Realtor, a real buyer who happens to
  // hold a licence.
  byTypeGroup: (function () {
    const m = {};
    for (const b of included) {
      // segment | types | tier - one key covering BOTH hold dimensions, so a
      // buyer who is VIP *and* JV is one group and gets subtracted once.
      // segment | types | tier | scrubOk - one key covering every hold
      // dimension, so a buyer held by two of them is subtracted once.
      const k = (b.segment || '') + '|' + (b.types || []).slice().sort().join(';')
              + '|' + (b.tier || '') + '|' + (b.scrubOk ? '1' : '0');
      m[k] = (m[k] || 0) + 1;
    }
    return m;
  })(),
  bySource: (function () {
    const m = {};
    for (const b of included) m[b.source] = (m[b.source] || 0) + 1;
    return m;
  })(),
  freshlyAddedCount: included.filter(b => b.freshlyAdded).length,
  excludedCount: excluded.length,
  suppressedCount: suppressed.length,
  included,
  excluded,
  suppressed,
  suggestions,
} }];

// Build the WhatsApp post DETERMINISTICALLY. No LLM touches these numbers:
// prices, comps and sqft render straight from the form, so they cannot be
// paraphrased, rounded, or invented.
const d = $input.first().json;
const p = d.props, f = d.raw;

const money = (n) => '$' + Number(n).toLocaleString('en-US');
const nf = (n) => Number(n).toLocaleString('en-US');
// Strip any bullet the user typed themselves - the template adds its own.
const lines = (s) => (s || '').split('\n').map(x => x.trim().replace(/^[-\u2022*\u00B7\u2013\u2014]+\s*/, '')).filter(Boolean);
const T = (v) => (v == null ? '' : String(v).trim());

const fullAddress = T(f['Address']).replace(/[,\s]+$/, '');
// Computed here, not read from upstream - the exclusion engine does not
// pass it through, which rendered 'Escrow: $NaN'.
const escrow = (!f['Escrow'] || Number(f['Escrow']) <= 0) ? 10000 : Number(f['Escrow']);
// 'unknown' typed into an age field should read as unknown, not 'is unknown'.
const UNK = (v) => /^(unknown|unk|n\/a|na|\?)$/i.test(T(v));

// ---- Details bullets, in the house order ----
// "3" in an age box means 3 years. Say so - "Roof is 3" reads like a typo.
const age = (v, label) => {
  const s = T(v);
  if (!s || UNK(s)) return label + ' age unknown';
  return label + ' is ' + (/^\d+(\.\d+)?$/.test(s) ? s + ' year' + (Number(s) === 1 ? '' : 's') + ' old' : s);
};
// A "none"-ish answer is good news for HOA and a non-event for liens, so they
// render differently: NO HOA is a selling point, "no liens" is just noise.
const NONEISH = (v) => /^(none|no|n\/a|na|0|none found|nothing|nothing found|clear|clean)$/i.test(T(v));

const details = [];
details.push('Beds/Bath: ' + T(f['Beds']) + '/' + T(f['Baths']));
details.push('Living Area: ' + nf(f['Living Area Sqft']) + ' sq ft');
if (f['Lot Size Sqft']) details.push('Lot Size: ' + nf(f['Lot Size Sqft']) + ' sq ft');
details.push(age(f['Roof Age'], 'Roof'));
details.push(age(f['AC Age'], 'AC'));
if (T(f['Key Upgrades'])) details.push('Upgrades: ' + T(f['Key Upgrades']));
for (const h of lines(f['Extra Highlights'])) details.push(h);
if (T(f['HOA'])) details.push(NONEISH(f['HOA']) ? 'NO HOA' : 'HOA: ' + T(f['HOA']));
// Only surface liens/violations when there is something to surface.
if (T(f['Liens or Violations']) && !NONEISH(f['Liens or Violations']))
  details.push('Liens/Violations: ' + T(f['Liens or Violations']));

// Extra Highlights is free text, so 'No HOA' typed there collides with the
// NO HOA bullet the HOA field generates. Last one wins, first position kept.
const seen = new Set();
const detailsOut = [];
for (const b of details) {
  const k = b.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (k && seen.has(k)) continue;
  seen.add(k);
  detailsOut.push(b);
}

const occupancy = T(f['Occupancy']);
const comps = lines(f['Comps']);

// ---- WhatsApp (single asterisks render as bold) ----
const wa = [];
wa.push('\uD83C\uDFE0 *' + fullAddress + '*');
wa.push('');
wa.push('\u2B50' + T(f['Headline']));
wa.push('');
wa.push('\uD83D\uDFE0 *Details*');
for (const b of detailsOut) wa.push(' \u00B7 ' + b);
if (occupancy) wa.push(' \u00B7 *' + occupancy + '*');
wa.push('');
wa.push('\uD83D\uDFE0 *Comps*');
for (const c of comps) wa.push(' \u00B7 ' + c);
wa.push('');
wa.push('\uD83D\uDCB0 *Price:* Only ' + money(f['Asking Price']));
wa.push('');
wa.push('\uD83D\uDCC8 *ARV:* ~' + money(f['ARV']));
wa.push('');
wa.push('\uD83D\uDCB5 *Escrow:* ' + money(escrow));
if (T(f['Photos Videos URL'])) {
  wa.push('');
  wa.push('\uD83D\uDCF8 *Photos & Video:* ' + T(f['Photos Videos URL']));
}
const whatsapp_post = wa.join('\n');

// ---- SMS: a DIFFERENT artifact, not the WhatsApp post with the bold removed.
//
// The first version was exactly that, and it did not arrive. 1,117 characters
// with emoji is 17 segments, because a single emoji forces the whole message
// into UCS-2 at 67 characters a segment instead of GSM-7 at 153. Seventeen
// segments with a link, from a new A2P number, to a cold buyer, is what
// carrier spam filters exist to stop. GHL accepted it and returned a
// messageId; the carrier marked it undelivered and nobody knew.
//
// So: plain GSM-7, compact separators, every real detail kept.

// Anything outside GSM-7 costs 2.3x. Fold what has an obvious equivalent and
// drop the rest rather than silently doubling the bill and the spam score.
const FOLD = { '‘': "'", '’': "'", '“': '"', '”': '"',
               '–': '-', '—': '-', '…': '...', '·': '-',
               ' ': ' ', '•': '-' };
const gsm = (s) => String(s == null ? '' : s)
  .split('').map(ch => FOLD[ch] !== undefined ? FOLD[ch] : (ch.charCodeAt(0) < 128 ? ch : ''))
  .join('').replace(/[ 	]+/g, ' ').trim();

// ---- Assemble as SECTIONS, not one run-on paragraph.
//
// The first working version packed every fact into three dense lines joined by
// '; ' and ' | '. It fit in four segments and it was unreadable on a phone.
//
// Bullets cost almost nothing here. A newline is one septet, the same as the
// space in '; ', and dropping the ' | ' separators actively SAVES septets:
// the pipe is a GSM-7 EXTENSION character, billed as two. So the readable
// version is roughly the same length as the cramped one.
const NL = String.fromCharCode(10);
const bullet = (s) => '- ' + s;

const head = [];
head.push(gsm(fullAddress));
if (T(f['Headline'])) head.push(gsm(T(f['Headline'])));

// The facts a cash buyer actually scans for, one per line.
const facts = [];
const spec = [];
if (T(f['Beds']) || T(f['Baths'])) spec.push(T(f['Beds']) + '/' + T(f['Baths']));
if (T(f['Living Area Sqft'])) spec.push(nf(f['Living Area Sqft']) + ' sqft');
if (T(f['Lot Size Sqft'])) spec.push(nf(f['Lot Size Sqft']) + ' lot');
if (spec.length) facts.push(bullet(gsm(spec.join(', '))));
if (T(f['Year Built'])) facts.push(bullet(gsm('Built ' + T(f['Year Built']))));
if (occupancy) facts.push(bullet(gsm(occupancy)));

// The spec bullets above already carry beds, baths, living area, lot and year,
// and the detail bullets repeat them verbatim. On WhatsApp that reads as a tidy
// summary; in a text it is a wasted segment.
// 'Roof age unknown' is not a detail - a buyer who cares will ask, and saying
// it costs the same as saying something true.
// No regex here on purpose: a word boundary written as backslash-b does not
// survive this file's trip through a shell and a JSON encoder, and became a
// literal backspace character that silently matched nothing.
const COVERED = ['beds/bath', 'beds/baths', 'living area', 'lot size', 'year built'];
const smsDetails = detailsOut.filter((b) => {
  const l = String(b).toLowerCase();
  if (COVERED.some((k) => l.indexOf(k) === 0)) return false;
  if (l.indexOf('age unknown') !== -1) return false;
  return true;
});
for (const dt of smsDetails) facts.push(bullet(gsm(dt)));

// Money gets its own block with a header, because it is the line buyers look
// for first and it should not be buried among the property facts.
const priceLines = [];
priceLines.push(gsm('PRICE ' + money(f['Asking Price'])));
if (T(f['ARV'])) priceLines.push(bullet(gsm('ARV ' + money(f['ARV']))));
if (escrow) priceLines.push(bullet(gsm('EMD ' + money(escrow))));
if (T(f['Close Date'])) priceLines.push(bullet(gsm('Close ' + T(f['Close Date']))));

const compLines = comps.length
  ? ['COMPS'].concat(comps.slice(0, 2).map((c) => bullet(gsm(c))))
  : [];

const photoLine = T(f['Photos Videos URL'])
  ? 'Photos: ' + gsm(T(f['Photos Videos URL']))
  : '';

// One assembler, four levels of degradation - so a long deal shortens
// predictably instead of getting silently sliced mid-word.
const assemble = (o) => {
  const secs = [];
  secs.push(head.join(NL));
  const fx = (o.maxFacts === undefined) ? facts : facts.slice(0, o.maxFacts);
  if (fx.length) secs.push(fx.join(NL));
  secs.push(priceLines.join(NL));
  if (o.comps !== false && compLines.length) secs.push(compLines.join(NL));
  if (photoLine) secs.push(photoLine);
  return secs.filter(Boolean).join(o.airy === false ? NL : NL + NL);
};

// Six GSM-7 segments is already a long text; past that the carrier filters
// start looking at you regardless of what it says.
//
// Degrade in the order a buyer would least miss. Blank lines go LAST, not
// first - readability is the entire point of this change, and comps are the
// cheapest thing in the message to lose.
const MAX = 153 * 6;
let sms_post = assemble({});
if (sms_post.length > MAX) sms_post = assemble({ comps: false });
for (let n = facts.length; n > 0 && sms_post.length > MAX; n--) {
  sms_post = assemble({ comps: false, maxFacts: n - 1 });
}
if (sms_post.length > MAX) sms_post = assemble({ comps: false, airy: false });

if (sms_post.length > MAX) {
  // Never cut the photos link - it is the whole point of the message.
  const room = MAX - photoLine.length - 2;
  let cut = sms_post.slice(0, room > 0 ? room : 0);
  const lastSpace = cut.lastIndexOf(' ');
  if (lastSpace > 0) cut = cut.slice(0, lastSpace);
  sms_post = cut + (photoLine ? NL + photoLine : '');
}

return [{ json: Object.assign({}, d, { viaConsole: !!d.viaConsole, fullAddress, whatsapp_post, sms_post }) }];

const res = $input.first().json;
const d = $('Build WhatsApp + SMS Post').first().json;

// Only one of Create/Update ran, so probe both. Referencing a node that did
// not execute throws, hence the try/catch rather than an if.
let recId = d.recordId || null;
if (!recId) { try { const r = $('Create Property').first().json; recId = (r.record && r.record.id) || r.id || null; } catch (e) {} }
if (!recId) { try { const r = $('Update Property').first().json; recId = (r.record && r.record.id) || r.id || null; } catch (e) {} }

let ai = {}, aiError = null;
try {
  const t = (res.content || []).find(b => b.type === 'text');
  ai = JSON.parse(t.text);
} catch (e) { aiError = String(e); }

return [{ json: {
  status: 'DRAFTS READY - NOTHING SENT',
  property_record_id: recId,
  property_action: d.created ? 'CREATED' : 'UPDATED existing record',
  address: d.fullAddress,
  viaConsole: !!d.viaConsole,
  buyers_included: d.includedCount,
  by_source: d.bySource,
  by_segment: d.bySegment,
  by_type_group: d.byTypeGroup,
  imported_last_2h: d.freshlyAddedCount,
  buyers_excluded: d.excludedCount,
  buyers_suppressed: d.suppressedCount,
  buyers_scanned: d.poolSize,
  not_buyers_skipped: d.notBuyers,
  pages_fetched: d.pagesFetched,
  whatsapp_post: d.whatsapp_post,
  sms_post: d.sms_post,
  teasers: {
    warm:         ai.teaser_warm || null,
    geo_cold:     ai.teaser_geo_cold || null,
    general_cold: ai.teaser_general_cold || null
  },
  // The warm version is the record's representative teaser; the console
  // sends back whatever was actually approved per segment.
  teaser_sms: ai.teaser_warm || ai.teaser_sms || null,
  hook_used: ai.hook_used || null,
  email_subject: ai.email_subject || null,
  voice_brief: ai.voice_brief || null,
  ai_error: aiError,
  included: d.included,
  excluded: d.excluded,
  suppressed: d.suppressed,
  review_suggestions: d.suggestions
} }];

// Build the Anthropic request as a real object. n8n's expression parser
// rejects a body this large inline ("invalid syntax"), so it lives here.
const d = $input.first().json;
const f = d.raw;

const SYSTEM = [
  'You write short outreach texts for Buying Hero, a South Florida wholesaler, to its cash-buyer list.',
  'You write THREE versions of the same deal, one per audience segment. Same facts, different opener.',
  'Non-negotiable rules:',
  '(1) NO version ever contains the street address - withholding it is what forces the reply. City or sub-market is fine.',
  '(2) Never invent exclusivity, urgency, competing offers, deadlines, or any claim you were not given.',
  '(3) Never state a number you were not given.',
  '(4) Sound like a person texting a contact. Short sentences, no emoji, no ALL CAPS, no marketing voice.',
  '(5) Use {{first_name}} where the buyer name goes. Andrew is the sender.',
  '(6) The two cold versions MUST identify Buying Hero by name and MUST end with an opt-out ("Reply STOP to opt out").',
  '    The two warm versions must NOT - these people know us and an opt-out line reads like spam to them.'
].join(' ');

const facts = [
  'City / sub-market: ' + (f['Neighborhood'] || d.derivedCity || f['City'] || ''),
  'County: ' + (f['County'] || ''),
  'Beds/Baths: ' + f['Beds'] + '/' + f['Baths'],
  'Type: ' + f['Property Type'],
  'ARV: ' + f['ARV'],
  'Asking: ' + f['Asking Price'],
  'Headline feature: ' + f['Headline'],
  'Occupancy: ' + (f['Occupancy'] || ''),
  '',
  'Additional details from the dispo manager:',
  (f['Additional Details'] || '(none provided - work from the facts above)'),
  '',
  'Write all four teasers plus the voice brief.'
].join('\n');

const T = 'Under 320 characters. Beds/baths, area, ARV, price, one standout feature, soft CTA. NO street address. ';

const claudeBody = {
  model: 'claude-opus-5',
  max_tokens: 8000,
  system: SYSTEM,
  messages: [{ role: 'user', content: facts }],
  output_config: {
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          teaser_warm:         { type: 'string', description: T + 'AUDIENCE: our own master list, existing relationship. Familiar, first-name, "got another one" energy. Do NOT write an opt-out line.' },
          teaser_geo_cold:     { type: 'string', description: T + 'AUDIENCE: cold, but they demonstrably buy within ~2 miles of this address. Lead with the neighborhood. Identify Buying Hero. Do NOT write an opt-out line - one exact sentence is appended in code.' },
          teaser_general_cold: { type: 'string', description: T + 'AUDIENCE: cold, no relationship and no geographic hook. Straight and credible. Identify Buying Hero. Do NOT write an opt-out line - one exact sentence is appended in code.' },
          hook_used:           { type: 'string', description: 'The warm opener line only, so it can be written to buy_last_hook and never reused on the same buyer.' },
          email_subject:       { type: 'string', description: 'Subject line for the email version.' },
          voice_brief:         { type: 'string', description: 'Plain fact sheet the voice AI answers from. Facts only, no script, no persuasion.' }
        },
        required: ['teaser_warm', 'teaser_geo_cold', 'teaser_general_cold', 'hook_used', 'email_subject', 'voice_brief'],
        additionalProperties: false
      }
    }
  }
};

return [{ json: Object.assign({}, d, { claudeBody }) }];

