parameters.jsCode:
// Read from Format Result - the save node's output is the GHL API response.
const d = $('Format Result').first().json;

// n8n sanitises the completion message: only structural tags survive and
// class/style attributes are stripped, so styling hangs off tag selectors in
// customCss. It also converts raw newlines to <br>, which would double-space
// inside <pre> - so emit ONE line of HTML and use <br> explicitly.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const block = (s) => esc(s).split('\n').join('<br>');

const H = [];

// --- status ---
H.push('<h1>Nothing has been sent</h1>');
H.push('<p>These are drafts. Review, then send manually or trigger the blast.</p>');

// --- deal summary ---
H.push('<h2>Deal</h2>');
H.push('<table><tr><th>Property</th><td>' + esc(d.address) + '</td></tr>' +
       '<tr><th>Record</th><td>' + esc(d.property_action) + '</td></tr>' +
       '<tr><th>Buyers included</th><td><b>' + esc(d.buyers_included) + '</b></td></tr>' +
       '<tr><th>Excluded by a rule</th><td>' + esc(d.buyers_excluded) + '</td></tr>' +
       '<tr><th>Suppressed</th><td>' + esc(d.buyers_suppressed) + ' (DNC, blacklist, or no phone)</td></tr>' +
       '<tr><th>Pool scanned</th><td>' + esc(d.buyers_scanned) + ' across ' + esc(d.pages_fetched) + ' page(s)</td></tr>' +
       '</table>');

// --- WhatsApp ---
H.push('<h2>WhatsApp post</h2>');
H.push('<p>Copy straight into the group.</p>');
H.push('<pre>' + block(d.whatsapp_post || '(not built)') + '</pre>');

// --- Teaser ---
H.push('<h2>Teaser SMS &mdash; first cold touch</h2>');
H.push('<p>No address. Withholding it is what earns the reply.</p>');
H.push('<pre>' + block(d.teaser_sms || '(not generated)') + '</pre>');
H.push('<p>Hook: <b>' + esc(d.hook_used || '-') + '</b> &nbsp;|&nbsp; Email subject: <b>' + esc(d.email_subject || '-') + '</b></p>');

// --- SMS full ---
H.push('<h2>SMS post &mdash; sent after a buyer replies</h2>');
H.push('<p>Same content as WhatsApp, asterisks stripped (SMS has no bold).</p>');
H.push('<pre>' + block(d.sms_post || '(not built)') + '</pre>');

// --- buyers ---
const rows = (arr, extra) => {
  if (!arr || !arr.length) return '<p>None.</p>';
  let t = '<table><tr><th>Buyer</th><th>Tier</th><th>Segment</th><th>Source</th><th>Phone</th>' + (extra ? '<th>' + extra + '</th>' : '') + '</tr>';
  for (const b of arr) {
    t += '<tr><td>' + esc(b.name) + (b.freshlyAdded ? ' <b>(new)</b>' : '') + '</td><td>' + esc(b.tier) +
         '</td><td>' + esc((SEGN[b.segment] || '').split(' · ')[0] || '') + '</td><td>' + esc(b.source || '') + '</td><td>' + esc(b.phone || '') + '</td>' +
         (extra ? '<td>' + esc(b.why || b.hint || '') + '</td>' : '') + '</tr>';
  }
  return t + '</table>';
};

// The blast form prefills from query params keyed on the field label.
const blastUrl = 'https://automations.buyinghero.com/form/send-blast'
  + '?Property%20Address=' + encodeURIComponent(d.address || '')
  + '&Teaser%20to%20send=' + encodeURIComponent(d.teaser_sms || '');
H.push('<h2>Send it</h2>');
H.push('<p><a href="' + blastUrl + '" target="_blank" rel="noopener">' +
       'Send teaser to ' + esc(d.buyers_included) + ' buyer(s)' + '</a></p>');
H.push('<p>Opens the blast page with the address and teaser already filled in - '
       + 'edit the teaser there if QA turned anything up. ' +
       'You still type SEND to confirm - that one word is the only thing between a ' +
       'stray click and a real text to every buyer on the list.</p>');

const SEGN = {
  warm: '1 · Warm master list',
  geo_cold: '2 · InvestorBase Matched — pulled for this address',
  general_cold: '3 · General cold — sourced for another deal'
};
H.push('<h2>Segments — who gets which script</h2>');
{
  const bs = d.by_segment || {};
  let t = '<table><tr><th>Segment</th><th>Buyers</th></tr>';
  for (const k of ['warm','geo_cold','general_cold'])
    t += '<tr><td>' + esc(SEGN[k]) + '</td><td><b>' + esc(bs[k] || 0) + '</b></td></tr>';
  H.push(t + '</table>');
  H.push('<p>Nobody is excluded for their source. Every buyer above is contacted - ' +
         'the segment only decides how cold the opener is.</p>');
}

H.push('<h2>Where these buyers came from</h2>');
{
  const bs = d.by_source || {};
  const keys = Object.keys(bs);
  if (!keys.length) {
    H.push('<p>No buyers matched.</p>');
  } else {
    let t = '<table><tr><th>Source</th><th>Buyers</th></tr>';
    for (const k of keys) t += '<tr><td>' + esc(k) + '</td><td><b>' + esc(bs[k]) + '</b></td></tr>';
    H.push(t + '</table>');
  }
  const fresh = d.imported_last_2h || 0;
  H.push('<p><b>' + esc(fresh) + '</b> of these were imported in the last 2 hours. ' +
         'If you just pulled an InvestorBase list for this address and that number ' +
         'looks low, the import is probably still running - wait a minute and submit again.</p>');
}

H.push('<h2>Buyers who would receive this</h2>');
H.push(rows(d.included));

H.push('<h2>Excluded &mdash; a human set this rule</h2>');
H.push(rows(d.excluded, 'Reason'));

H.push('<h2>Worth a call</h2>');
H.push('<p>Old notes disagree with this deal, but no exclusion rule is set. They still received it. Confirm, then set a rule if it is true.</p>');
H.push(rows(d.review_suggestions, 'What the notes say'));

// --- voice ---
H.push('<h2>Voice AI brief</h2>');
H.push('<pre>' + block(d.voice_brief || '(not generated)') + '</pre>');

// single line - no raw newlines anywhere
const summary_html = H.join('');

return [{ json: Object.assign({}, d, { summary_html }) }];

// Build the exact JSON contract the Dispo Deal Console renders.
// Shape is asserted by console/smoke.js against dist/index.html - if this
// changes, that test changes with it.
const d = $('Format Result').first().json;

const SEG = [
  { k: 'warm',         n: '01', key: 'Warm list',        desc: 'Existing relationships',               hot: false },
  { k: 'geo_cold',     n: '02', key: 'InvestorBase Matched', desc: 'InvestorBase pulled them for THIS address', hot: false },
  { k: 'general_cold', n: '03', key: 'General cold',     desc: 'Sourced for a different deal',         hot: false }
];

const bySeg = d.by_segment || {};
const teasers = d.teasers || {};
// Per-blast hold by buyer type. These are NOT exclusions - a JV partner is a
// real buyer - but the first blast to a freshly imported list goes to end
// buyers only, so JV and Realtor arrive pre-held and the dispo manager can
// release either one with a checkbox.
// TEST is held by default for the same reason JV and Realtor are, but more
// strictly: a messaging-test record must never ride along on a real blast.
const HOLD_BY_DEFAULT = ['JV', 'Realtor', 'TEST'];
// Tiers are NOT held by default. VIPs are the buyers we most want on a deal;
// the reason to hold them is that they get a phone call instead of a text, and
// that is a per-deal judgement the dispo manager makes, not a standing rule.
const TIERS_HELD_BY_DEFAULT = [];
const groups = d.by_type_group || {};
const parse = (k) => {
  const p = k.split('|');
  return { seg: p[0], types: (p[1] || '').split(';').filter(Boolean), tier: p[2] || '',
           scrubOk: p[3] === '1' };
};

// Every distinct value actually present, with a real count, so the UI never
// offers a checkbox for a type or tier nobody in this pool has.
const typeTotals = {}, tierTotals = {};
for (const k of Object.keys(groups)) {
  const g = parse(k);
  for (const t of g.types) typeTotals[t] = (typeTotals[t] || 0) + groups[k];
  if (g.tier && g.tier !== '(none)') tierTotals[g.tier] = (tierTotals[g.tier] || 0) + groups[k];
}
const buyerTypes = Object.keys(typeTotals).sort().map(t => ({
  key: t, count: typeTotals[t], heldByDefault: HOLD_BY_DEFAULT.indexOf(t) !== -1
}));
const TIER_ORDER = { VIP: 0, A: 1, B: 2, C: 3 };
const buyerTiers = Object.keys(tierTotals)
  .sort((a, b) => (TIER_ORDER[a] == null ? 9 : TIER_ORDER[a]) - (TIER_ORDER[b] == null ? 9 : TIER_ORDER[b]))
  .map(t => ({ key: t, count: tierTotals[t],
               heldByDefault: TIERS_HELD_BY_DEFAULT.indexOf(t) !== -1 }));

const segments = SEG.map(s => ({
  n: s.n, key: s.key, desc: s.desc, hot: s.hot,
  count: Number(bySeg[s.k] || 0),
  teaser: teasers[s.k] || '',
  // [{types:['JV','Realtor'], count:1}, ...] for THIS segment. The console
  // subtracts whole groups, so a buyer carrying two held types is only ever
  // counted once.
  typeGroups: Object.keys(groups)
    .filter(k => parse(k).seg === s.k)
    .map(k => ({ types: parse(k).types, tier: parse(k).tier,
                 scrubOk: parse(k).scrubOk, count: groups[k] }))
}));

// The table shows the top of the list, not all 600 - the browser does not need
// the whole pool and the counts above already carry the totals.
const SHOW = 60;
const trim = (arr, f) => (arr || []).slice(0, SHOW).map(f);

const segLabel = {};
for (const s of SEG) segLabel[s.k] = s.key;

const sources = Object.keys(d.by_source || {}).map(k => ({ name: k, count: d.by_source[k] }))
  .sort((a, b) => b.count - a.count);

return [{ json: {
  ok: true,
  propertyId: d.property_record_id,
  address: d.address,
  recordAction: /CREATED/.test(String(d.property_action)) ? 'created' : 'updated',
  segments,
  buyerTypes,
  buyerTiers,
  // Purchased-list buyers with no DNC + litigator scrub on file. Held by
  // default; the review page can release them deliberately.
  unscrubbed: Object.keys(groups)
    .filter(k => !parse(k).scrubOk)
    .reduce((a, k) => a + groups[k], 0),
  sources,
  importedLast2h: d.imported_last_2h,
  included: trim(d.included, b => ({
    name: b.name, tier: b.tier, segment: segLabel[b.segment] || b.segment || '',
    source: b.source || '', phone: b.phone || '',
    // Carried so the table can show which of these a per-blast hold removes.
    // Without it the list reads as "these 121 are getting the text" while the
    // send quietly drops 31 of them.
    types: b.types || []
  })),
  excluded: trim((d.excluded || []).concat(d.suppressed || []), b => ({
    name: b.name, phone: b.phone || '', reason: b.why || ''
  })),
  worthACall: trim(d.review_suggestions, b => ({
    name: b.name, phone: b.phone || '', note: b.hint || ''
  })),
  whatsappPost: d.whatsapp_post || '',
  smsPost: d.sms_post || '',
  voiceBrief: d.voice_brief || '',
  // Surfaced so a Claude failure is visible in the UI rather than showing up
  // as four silently blank teaser boxes.
  aiError: d.ai_error || null,
  counts: {
    scanned: d.buyers_scanned, included: d.buyers_included,
    excluded: d.buyers_excluded, suppressed: d.buyers_suppressed,
    notBuyers: d.not_buyers_skipped
  }
} }];
